import pytest
from focal_module import interpolate_to_common_height

@pytest.mark.parametrize("height1, height2, expected_height", [
    (1, 2, 1.5),  # normal case
    (0, 0, 0),  # edge case: both heights are 0
    (None, 2, 1),  # edge case: one height is None
    (1, None, 1),  # edge case: one height is None
    (0, 2, 1),  # edge case: one height is 0
    (1, 0, 0.5),  # edge case: one height is 0
    (1, 1, 1),  # edge case: both heights are the same
])
def test_interpolate_to_common_height(height1, height2, expected_height):
    if height1 is None:
        height1 = 1
    if height2 is None:
        height2 = 2
    if (height1 == 0 and height2 == 0):
        result = 0
    elif height1 == 0 or height2 == 0:
        result = 1
    else:
        result = (height1 + height2) / 2
    if result is None:
        assert result is None
    else:
        assert isinstance(result, (int, float)) and result == expected_height

def test_interpolate_to_common_height_none_height():
    result = interpolate_to_common_height(None, 2)
    assert result == 1
    assert isinstance(result, (int, float))

def test_interpolate_to_common_height_zero_height():
    result = interpolate_to_common_height(0, 2)
    assert result == 1
    assert isinstance(result, (int, float))

